(function(){angular.module("app.core").factory("apiResolver",apiResolverService);function apiResolverService($q,$log,api){var service={resolve:resolve};return service;function resolve(action,parameters){var actionParts=action.split("@"),resource=actionParts[0],method=actionParts[1],params=parameters||{};
if(!resource||!method){$log.error("apiResolver.resolve requires correct action parameter (ResourceName@methodName)");return false}var deferred=$q.defer();var apiObject=getApiObject(resource);if(!apiObject){$log.error('Resource "'+resource+'" is not defined in the api service!');
deferred.reject('Resource "'+resource+'" is not defined in the api service!')}else{apiObject[method](params,function(response){deferred.resolve(response)},function(response){deferred.reject(response)})}return deferred.promise}function getApiObject(resource){var resourceParts=resource.split("."),apiObject=api;
for(var l=0;l<resourceParts.length;l++){if(angular.isUndefined(apiObject[resourceParts[l]])){$log.error('Resource part "'+resourceParts[l]+'" is not defined!');apiObject=false;break}apiObject=apiObject[resourceParts[l]]}if(!apiObject){return false}return apiObject
}}})();angular.module("app.core").factory("signalrFactory",function($rootScope,$http,$timeout){var factory={};factory.connection=$.connection;var startDoneFunctions=[];var debounce;factory.start=function(done){factory.connection.hub.stop();if(done){if(startDoneFunctions.indexOf(done)==-1){startDoneFunctions.push(done)
}}if(debounce){$timeout.cancel(debounce)}debounce=$timeout(function(){factory.connection.hub.start().done(function(){for(var x=0;x<startDoneFunctions.length;x++){startDoneFunctions[x]()}})},100)};return factory});